    def items(self):
        return [
            "apps.pages:about",
            "apps.pages:contact",
            "apps.pages:faqs",
            "apps.pages:index",
        ]

class HomePageView(TemplateView):
    template_name = "pages/index.html"
    def get_context_data(self, **kwargs):
        context = super().get_context_data(**kwargs)
        context["posts"] = Post.published.all()[:8]
        return context
class ContactUsView(CreateView):
