def timeit(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        starttime = time.time()
        value = func(*args, **kwargs)
        endtime = time.time()
        print(f"func name: {func.__name__} take time: {endtime - starttime}")
        return value
    return wrapper
