def sanitize_filename(filename):
    filename = os.path.basename(filename)
    filename = filename.replace("\x00", "").replace("/", "").replace("\\", "")
    filename = filename.replace(" ", "_")
    filename = re.sub(r"[^\w\-.]", "", filename)
    name, ext = os.path.splitext(filename)
    if len(name) > 100:
        name = name[:100]
    return f"{name}{ext}"
